package com.ruoyi.ai.agent;

import com.ruoyi.ai.domain.dto.*;
import com.ruoyi.common.core.domain.R;
import com.ruoyi.common.core.context.SecurityContextHolder;
import com.fasterxml.jackson.databind.ObjectMapper;
import junit.framework.TestCase;
import java.util.*;
import static com.ruoyi.ai.agent.AgentJson.*;

public class B10VersionBoundaryMysqlTest extends TestCase {
    private A1TestFixture f;private long book;private String first;private final String a="{\"v\":1}",b="{\"v\":2}",c="{\"v\":3}";
    protected void setUp() throws Exception {f=new A1TestFixture(true);book=f.seed("{\"v\":0}");R<Map<String,Object>> initial=commit(request(a));assertEquals(200,initial.getCode());first=String.valueOf(initial.getData().get("commitId"));}
    protected void tearDown(){f.close();}
    private CommitRequest request(String content){Map<String,Object> state=f.status(book);@SuppressWarnings("unchecked") Map<String,Object> draft=(Map<String,Object>)state.get("workingState");CommitRequest r=new CommitRequest();r.setBranchId(((Number)state.get("branchId")).longValue());r.setBaseVersion(((Number)state.get("version")).longValue());r.setBaseCommitId((String)state.get("headCommitId"));r.setExpectedDraftVersion(draft==null?-1L:((Number)draft.get("version")).longValue());r.setLoadedRevision((String)state.get("loadedRevision"));r.setContent(content);r.setOperationId(UUID.randomUUID().toString());r.setCommitMessage("manual version");r.setSource("manual");r.setActionSchemaVersion("2.0");r.setExecutedChanges(Collections.singletonList(Collections.singletonMap("kind",(Object)"manual-snapshot")));return r;}
    private R<Map<String,Object>> commit(CommitRequest r){f.identity();return f.tx.execute(tx->f.service.commit(book,r));}
    private R<Map<String,Object>> restore(String id,CommitRequest r){f.identity();return f.tx.execute(tx->f.service.restore(book,id,r));}
    private void draft(String content){CommitRequest binding=request(content);WorkingStateRequest r=f.request(book,binding.getExpectedDraftVersion(),binding.getLoadedRevision(),content);r.setBaseVersion(binding.getBaseVersion());r.setBaseCommitId(binding.getBaseCommitId());assertEquals(200,f.save(book,r).getCode());}
    private int count(){return f.db.queryForObject("select count(*) from ai_workbook_commit where workbook_id=?",Integer.class,book);}
    private String draftContent(){return f.db.queryForObject("select cast(draft_snapshot as char character set utf8mb4) from ai_workbook_working_state where workbook_id=?",String.class,book);}
    private CommitRequest copy(CommitRequest r){return new ObjectMapper().convertValue(r,CommitRequest.class);}
    private void noCommit(int count,String head){assertEquals(count,count());assertEquals(head,f.db.queryForObject("select head_commit_id from ai_workbook where workbook_id=?",String.class,book));}
    public void testFreshManualFullSnapshotCommit(){CommitRequest r=request(b);R<Map<String,Object>> saved=commit(r);assertEquals(200,saved.getCode());assertEquals(b,String.valueOf(f.status(book).get("content")));assertEquals(2,count());assertEquals(200,f.service.snapshot(book,first).getCode());}
    public void testSameHeadStaleCommitCannotDeleteNewDraft(){CommitRequest stale=request(c);draft(b);assertEquals(409,commit(stale).getCode());assertEquals(b,draftContent());noCommit(1,first);}
    public void testFreshBindingMayCommitAdditionalLocalManualChanges(){draft(b);CommitRequest fresh=request(c);assertEquals(200,commit(fresh).getCode());assertEquals(c,f.status(book).get("content"));assertEquals(0,f.db.queryForObject("select count(*) from ai_workbook_working_state where workbook_id=?",Integer.class,book).intValue());}
    public void testMissingOrForgedDraftBindingFailsClosed(){for(int mode=0;mode<4;mode++){CommitRequest r=request(b);if(mode==0)r.setExpectedDraftVersion(null);if(mode==1)r.setLoadedRevision(null);if(mode==2)r.setExpectedDraftVersion(-2L);if(mode==3)r.setLoadedRevision("forged");assertEquals(409,commit(r).getCode());}noCommit(1,first);}
    public void testStaleBranchAndHeadRejected(){CommitRequest r=request(b);r.setBaseVersion(0L);assertEquals(409,commit(r).getCode());r=request(b);r.setBaseCommitId("forged");assertEquals(409,commit(r).getCode());r=request(b);r.setBranchId(r.getBranchId()+1);assertEquals(409,commit(r).getCode());noCommit(1,first);}
    public void testRepeatedCommitReturnsOriginalFactAndPreservesLaterDraft(){CommitRequest r=request(b);Map<String,Object> saved=commit(r).getData();draft(c);R<Map<String,Object>> retry=commit(copy(r));assertEquals(200,retry.getCode());assertEquals(saved.get("commitId"),retry.getData().get("commitId"));assertEquals(((Number)saved.get("branchVersion")).longValue(),((Number)retry.getData().get("branchVersion")).longValue());assertEquals(((Number)saved.get("workbookVersion")).longValue(),((Number)retry.getData().get("workbookVersion")).longValue());assertEquals(c,draftContent());assertEquals(2,count());}
    public void testSameOperationDifferentParametersRejected(){CommitRequest r=request(b);assertEquals(200,commit(r).getCode());for(int mode=0;mode<11;mode++){CommitRequest changed=copy(r);switch(mode){case 0:changed.setContent(c);break;case 1:changed.setCommitMessage("other");break;case 2:changed.setSource("ai");break;case 3:changed.setBranchId(9999L);break;case 4:changed.setBaseVersion(9999L);break;case 5:changed.setBaseCommitId("other");break;case 6:changed.setExpectedDraftVersion(99L);break;case 7:changed.setLoadedRevision("other");break;case 8:changed.setPlannedActions(Collections.singletonList("forged"));break;case 9:changed.setExecutionContext(Collections.singletonMap("forged",true));break;case 10:changed.setExecutedChanges(Collections.singletonList(Collections.singletonMap("kind",(Object)"other")));break;}assertEquals("mode "+mode,409,commit(changed).getCode());}assertEquals(2,count());}
    public void testRequestMapOrderDoesNotChangeIdentity(){CommitRequest r=request(b);Map<String,Object> data=new LinkedHashMap<>();data.put("a",1);data.put("b",2);r.setDataContext(data);assertEquals(200,commit(r).getCode());CommitRequest same=copy(r);Map<String,Object> reordered=new LinkedHashMap<>();reordered.put("b",2);reordered.put("a",1L);same.setDataContext(reordered);assertEquals(200,commit(same).getCode());assertEquals(2,count());}
    public void testLegacyCommitStillReadableButOperationCannotBeReused(){CommitRequest r=request(b);String id=String.valueOf(commit(r).getData().get("commitId"));f.db.update("update ai_workbook_commit set validation_json='{\"hashVerified\":true}' where commit_id=?",id);assertEquals(409,commit(r).getCode());assertEquals(200,f.service.snapshot(book,id).getCode());assertEquals(200,f.service.commitDetail(book,id).getCode());assertEquals(2,count());}
    public void testIncompleteOriginalFactCannotReturnFabricatedVersions(){CommitRequest r=request(b);String id=String.valueOf(commit(r).getData().get("commitId"));f.db.update("update ai_workbook_commit set validation_json=json_remove(validation_json,'$.branchVersionAfter') where commit_id=?",id);assertEquals(409,commit(r).getCode());assertEquals(2,count());}
    public void testRestoreStaleDraftBindingCannotDeleteNewDraft(){CommitRequest stale=request(null);draft(b);assertEquals(409,restore(first,stale).getCode());assertEquals(b,draftContent());noCommit(1,first);}
    public void testRestoreFreshDirtyDraftStillRequiresExplicitResolution(){draft(b);CommitRequest fresh=request(null);assertEquals(409,restore(first,fresh).getCode());assertEquals(b,draftContent());noCommit(1,first);}
    public void testRestoreAllowsCleanAutosavedDraftAndSameRetry(){draft(a);CommitRequest r=request(null);R<Map<String,Object>> result=restore(first,r);assertEquals(200,result.getCode());assertEquals(a,f.status(book).get("content"));assertEquals(200,restore(first,copy(r)).getCode());assertEquals(2,count());}
    public void testHistoricalRestoreUsesTrustedSnapshotAndKeepsHistory(){String second=String.valueOf(commit(request(b)).getData().get("commitId"));CommitRequest r=request("forged-client-snapshot");R<Map<String,Object>> result=restore(first,r);assertEquals(200,result.getCode());assertEquals(a,f.status(book).get("content"));assertEquals("revert",result.getData().get("source"));assertEquals(second,result.getData().get("parentCommitId"));assertEquals(3,count());assertEquals(b,f.service.snapshot(book,second).getData().get("content"));assertEquals(409,restore(second,copy(r)).getCode());assertEquals(3,count());}
    public void testCorruptHistoricalSnapshotRejected(){commit(request(b));String head=String.valueOf(f.status(book).get("headCommitId"));CommitRequest r=request(null);f.db.update("update ai_workbook_snapshot set content_hash='forged' where commit_id=?",first);assertEquals(422,restore(first,r).getCode());noCommit(2,head);}
    public void testCorruptCurrentDraftCannotCommitOrRestore(){draft(b);CommitRequest r=request(c),restore=request(null);f.db.update("update ai_workbook_working_state set content_hash='forged' where workbook_id=?",book);assertEquals(409,commit(r).getCode());assertEquals(409,restore(first,restore).getCode());assertEquals(b,draftContent());noCommit(1,first);}
    public void testActiveOrUnresolvedLeaseBlocksBothManualMutations(){for(long expiry:new long[]{System.currentTimeMillis()+120000,0}){CommitRequest r=request(b),restore=request(null);f.db.update("insert into ai_agent_lease(workbook_id,run_id,fencing_token,expires_at) values(?,?,1,?) on duplicate key update expires_at=values(expires_at)",book,"test-lease",expiry);try{commit(r);fail("active lease bypass");}catch(IllegalArgumentException expected){}try{restore(first,restore);fail("restore lease bypass");}catch(IllegalArgumentException expected){}noCommit(1,first);}}
    public void testOtherUserCannotCommitOrRestore(){CommitRequest r=request(b);SecurityContextHolder.setUserId("2");R<Map<String,Object>> commit=f.tx.execute(tx->f.service.commit(book,r)),restore=f.tx.execute(tx->f.service.restore(book,first,r));assertTrue(commit.getCode()!=200);assertTrue(restore.getCode()!=200);f.identity();noCommit(1,first);}
}
